func evaluate(t *testing.T, rule func(*Inputs) []Insight, inputs *Inputs) []Insight {
	t.Helper()
	if inputs.Now.IsZero() {
		inputs.Now = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
	}
	inputs.Thresholds = inputs.Thresholds.withDefaults()
	inputs.conditions, inputs.touched = map[string]time.Time{}, map[string]struct{}{}
	return rule(inputs)
}

func diskTimeToFull(inputs *Inputs) []Insight {
	var out []Insight
	thresholds := inputs.Thresholds
	for _, member := range members(inputs) {
		if member.System == nil {
			continue
		}
		for _, filesystem := range member.System.Filesystems {
			if filesystem.SizeBytes == 0 {
				continue
			}
			size := float64(filesystem.SizeBytes)
			used := size - float64(min(filesystem.AvailBytes, filesystem.SizeBytes))
			ratio := used / size
			entity := Entity{Kind: "host", ID: member.Member + ":" + filesystem.Role, Href: memberHref(member.Member)}
			labels := map[string]string{"member": member.Member, "role": filesystem.Role}
			usedEvidence := Evidence{Label: "Used", Metric: observability.HistFSRatio, Labels: labels, Value: ratio,
				Unit: "ratio", Comparison: "<", Threshold: threshold(thresholds.DiskUsedWarning)}
			action := Action{Label: "Find what is growing", Command: "du -xh --max-depth=2 " + filesystem.Path + " | sort -h | tail"}
			// Both criteria are evaluated and the worse one wins, under one
			// key per filesystem: crossing the usage warning must not
			// downgrade a disk that fills within hours, nor resolve and
			// reopen the same problem under a new key.
			var candidates []Insight
			if ratio >= thresholds.DiskUsedWarning {
				severity := SeverityWarning
				evidence := usedEvidence
				if ratio >= thresholds.DiskUsedCritical {
					severity = SeverityCritical
					evidence.Threshold = threshold(thresholds.DiskUsedCritical)
				}
				candidates = append(candidates, Insight{Severity: severity, Score: ratio * 100,
					Title: fmt.Sprintf("%s %s filesystem is %.0f%% full", member.Member, filesystem.Role, ratio*100),
					Why: fmt.Sprintf("The %s filesystem (%s) on %s has %s free.", filesystem.Role, filesystem.Path,
						member.Member, bytesText(float64(filesystem.AvailBytes))),
					Evidence: []Evidence{evidence}})
			}
			if ttf, rate, ok := timeToFull(inputs, labels, size, used); ok && ttf < thresholds.DiskTimeToFullWarning {
				severity := SeverityWarning
				limit := thresholds.DiskTimeToFullWarning
				if ttf < thresholds.DiskTimeToFullCritical {
					severity, limit = SeverityCritical, thresholds.DiskTimeToFullCritical
				}
				candidates = append(candidates, Insight{Severity: severity, Score: 1e6 / max(ttf.Hours(), 0.01),
					Title: fmt.Sprintf("%s %s filesystem full in about %s", member.Member, filesystem.Role, roundDuration(ttf)),
					Why: fmt.Sprintf("The %s filesystem on %s grows %s per hour and has %s free, so it fills in about %s.",
						filesystem.Role, member.Member, bytesText(rate*3600), bytesText(size-used), roundDuration(ttf)),
					Evidence: []Evidence{{Label: "Time to full", Value: ttf.Hours(), Unit: "h", Comparison: ">=",
						Threshold: threshold(limit.Hours())},
						{Label: "Growth", Metric: observability.HistFSUsed, Labels: labels, Value: rate * 3600, Unit: "bytes/h"},
						usedEvidence}})
			}
			if len(candidates) == 0 {
				continue
			}
			worst := candidates[0]
			for _, candidate := range candidates[1:] {
				if candidate.Severity.Rank() > worst.Severity.Rank() {
					worst = candidate
				}
			}
			worst.Key, worst.Entity, worst.Actions = "disk:"+entity.ID, entity, []Action{action}
			out = append(out, worst)
		}
	}
	return out
}

// timeToFull fits a least-squares line through the filesystem's used bytes
// over the last six hours of history. It needs at least 30 minutes of data
// and a growing trend.
func timeToFull(inputs *Inputs, labels map[string]string, size, used float64) (time.Duration, float64, bool) {
	if inputs.History == nil {
		return 0, 0, false
	}
	result := inputs.History.Range(observability.HistoryQuery{Metric: observability.HistFSUsed, Labels: labels,
		Start: inputs.Now.Add(-6 * time.Hour), End: inputs.Now, Tier: observability.Tier1m, MaxSeries: 1})
	if len(result.Series) == 0 {
		return 0, 0, false
	}
	points := result.Series[0].Points
	if len(points) < 5 || points[len(points)-1].Time.Sub(points[0].Time) < 30*time.Minute {
		return 0, 0, false
	}
	origin := points[0].Time
	var sumX, sumY, sumXY, sumXX float64
	for _, point := range points {
		x := point.Time.Sub(origin).Seconds()
		sumX += x
		sumY += point.Value
		sumXY += x * point.Value
		sumXX += x * x
	}
	count := float64(len(points))
	denominator := count*sumXX - sumX*sumX
	if denominator == 0 {
		return 0, 0, false
	}
	slope := (count*sumXY - sumX*sumY) / denominator // bytes per second
	if slope <= 0 {
		return 0, 0, false
	}
	seconds := (size - used) / slope
	if seconds > (365 * 24 * time.Hour).Seconds() {
		return 0, 0, false
	}
	return time.Duration(seconds * float64(time.Second)), slope, true
}

func ociErrors(inputs *Inputs) []Insight {
	if inputs.History == nil {
		return nil
	}
	window := inputs.Thresholds.OCIWindow
	perMinute := func(metric string) map[string]float64 {
		result := inputs.History.Range(observability.HistoryQuery{Metric: metric, Start: inputs.Now.Add(-window),
			End: inputs.Now, Tier: observability.TierRaw, Rate: true, MaxSeries: 256})
		rates := map[string]float64{}
		for _, series := range result.Series {
			if len(series.Points) == 0 {
				continue
			}
			var sum float64
			for _, point := range series.Points {
				sum += point.Value
			}
			rates[series.Labels["operation"]] = sum / float64(len(series.Points)) * 60
		}
		return rates
	}
	var out []Insight
	add := func(kind, metric string, limit float64, title, why string) {
		rates := perMinute(metric)
		total := 0.0
		var worst []string
		for _, operation := range slices.Sorted(maps.Keys(rates)) {
			total += rates[operation]
			if rates[operation] > 0 {
				worst = append(worst, fmt.Sprintf("%s %.1f/min", operation, rates[operation]))
			}
		}
		if total < limit {
			return
		}
		severity := SeverityWarning
		if total >= limit*10 {
			severity = SeverityCritical
		}
		out = append(out, Insight{Severity: severity, Score: total, Key: "oci_errors:" + kind, Title: title,
			Why:    fmt.Sprintf(why, total, roundDuration(window)),
			Entity: Entity{Kind: "operation", ID: kind, Href: "/oci"},
			Evidence: []Evidence{{Label: "Rate", Metric: metric, Value: total, Unit: "per min", Comparison: "<",
				Threshold: threshold(limit)}, {Label: "By operation", Text: strings.Join(worst, ", ")}},
			Actions: []Action{{Label: "Open OCI", Href: "/oci"}}})
	}
	add("errors", observability.HistOCIErrors, inputs.Thresholds.OCIErrorsPerMinute, "OCI API errors are elevated",
		"OCI calls failed %.1f times per minute over the last %s.")
	add("throttled", observability.HistOCIThrottled, inputs.Thresholds.OCIThrottledPerMinute,
		"OCI is throttling the orchestrator (429)",
		"OCI returned 429 Too Many Requests %.1f times per minute over the last %s; calls are backing off.")
	return out
}

// History is a bounded in-memory time-series store of key metrics with
// raw -> 1m -> 5m -> 1h downsampling over 14 days. It is safe for concurrent
// use; Append and Range never perform I/O.
type History struct {
	config       HistoryConfig
	mu           sync.RWMutex
	series       map[string]*series
	dropped      uint64
	dropMinutes  map[int64]bool
	newestMinute int64
}

// NewHistory returns an empty store.
func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

// HistoryMetrics is the history store's metric set.
var HistoryMetrics = metrics.NewSet()

var (
	historyDropped = HistoryMetrics.NewCounter(MetricPrefix + "history_series_dropped_total")
	historySamples = HistoryMetrics.NewCounter(MetricPrefix + "history_samples_total")
)

func seriesKey(metric string, labels []Label) string {
	pairs := make([]string, 0, len(labels)*2)
	for _, label := range labels {
		pairs = append(pairs, label.Name, label.Value)
	}
	return Series(metric, pairs...)
}

func sortedLabels(labels []Label) []Label {
	labels = slices.Clone(labels)
	slices.SortFunc(labels, func(left, right Label) int { return cmp.Compare(left.Name, right.Name) })
	return labels
}

func (history *History) newSeries(metric string, labels []Label, counter bool) *series {
	interval := history.config.Interval
	return &series{metric: metric, labels: labels, counter: counter, tiers: map[string]*tier{
		TierRaw: newTier(0, rawRetention, interval),
		Tier1m:  newTier(time.Minute, oneMinuteRetention, interval),
		Tier5m:  newTier(5*time.Minute, fiveMinuteRetention, interval),
		Tier1h:  newTier(time.Hour, HistoryRetention, interval),
	}}
}

// Append stores one batch of samples taken at the same time. NaN and
// infinite values are skipped.
func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

