type clock struct {
	mu  sync.Mutex
	now time.Time
}

func (c *clock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *clock) Advance(step time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(step)
	c.mu.Unlock()
}

type fakeCluster struct {
	mu       sync.Mutex
	snapshot observability.ClusterSnapshot
	err      error
}

func (cluster *fakeCluster) Cluster(context.Context, bool) (observability.ClusterSnapshot, error) {
	cluster.mu.Lock()
	defer cluster.mu.Unlock()
	return cluster.snapshot, cluster.err
}

func (cluster *fakeCluster) set(snapshot observability.ClusterSnapshot) {
	cluster.mu.Lock()
	cluster.snapshot = snapshot
	cluster.mu.Unlock()
}

func controller(name string, leader bool) observability.MemberSnapshot {
	return observability.MemberSnapshot{Member: name, Role: "controller", Ready: true, BuildVersion: "v1",
		Authority: &observability.AuthorityView{Leader: leader, Ready: true, OwnerID: "0000000000KZ5R9PYPCAJ654M2", Epoch: 3}}
}

func healthy() observability.ClusterSnapshot {
	return observability.ClusterSnapshot{Cell: "gru", Expected: []string{"c1", "c2", "c3"},
		Members: []observability.MemberSnapshot{controller("c1", true), controller("c2", false), controller("c3", false)}}
}

func find(insights []Insight, rule string) *Insight {
	for index := range insights {
		if insights[index].Rule == rule {
			return &insights[index]
		}
	}
	return nil
}

type localSource struct{ snapshot observability.MemberSnapshot }

func (source localSource) Snapshot(context.Context, bool) (observability.MemberSnapshot, error) {
	return source.snapshot, nil
}

func evaluate(t *testing.T, rule func(*Inputs) []Insight, inputs *Inputs) []Insight {
	t.Helper()
	if inputs.Now.IsZero() {
		inputs.Now = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
	}
	inputs.Thresholds = inputs.Thresholds.withDefaults()
	inputs.conditions, inputs.touched = map[string]time.Time{}, map[string]struct{}{}
	return rule(inputs)
}

func (inputs *Inputs) Since(key string) time.Duration {
	inputs.touched[key] = struct{}{}
	if inputs.owners != nil {
		inputs.owners[key] = inputs.rule
	}
	started, ok := inputs.conditions[key]
	if !ok {
		inputs.conditions[key] = inputs.Now
		return 0
	}
	return inputs.Now.Sub(started)
}

// Rule is one named check.
type Rule struct {
	Name        string
	Description string
	Evaluate    func(inputs *Inputs) []Insight
}

// Evaluation is the result of one pass.
type Evaluation struct {
	At       time.Time `json:"at"`
	Insights []Insight `json:"insights"`
	Counts   Counts    `json:"counts"`
	// Unavailable names inputs that could not be read this pass.
	Unavailable []string `json:"unavailable,omitempty"`
}

// Source is the read side the dashboard and the region provider use.
// Engine implements it.
type Source interface {
	// Current returns the latest evaluation's ranked insights.
	Current() Evaluation
	// Changes returns transitions at or after since, oldest first.
	Changes(since time.Time) []Change
	// Subscribe streams transitions until ctx ends.
	Subscribe(ctx context.Context, buffer int) <-chan Change
}

// Engine evaluates rules and tracks open insights.
type Engine struct {
	// droppedThrough is the time of the newest change dropped for capacity.
	droppedThrough time.Time
	config         Config
	rules          []Rule

	mu         sync.Mutex
	conditions map[string]time.Time
	// owners names the rule that started each condition timer.
	owners      map[string]string
	open        map[string]Insight
	current     Evaluation
	changes     []Change
	subscribers map[*changeSubscriber]struct{}
}

type changeSubscriber struct{ changes chan Change }

// NewEngine returns an engine over config.
func NewEngine(config Config) *Engine {
	if config.Interval <= 0 {
		config.Interval = DefaultInterval
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	config.Region = strings.ToLower(config.Region)
	config.Thresholds = config.Thresholds.withDefaults()
	rules := config.Rules
	if rules == nil {
		rules = DefaultRules()
	}
	return &Engine{config: config, rules: rules, conditions: map[string]time.Time{}, owners: map[string]string{},
		open: map[string]Insight{}, subscribers: map[*changeSubscriber]struct{}{}}
}

func (engine *Engine) gather(ctx context.Context, now time.Time) (*Inputs, []string) {
	config := engine.config
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	inputs := &Inputs{Now: now, Region: config.Region, Thresholds: config.Thresholds, History: config.History}
	var unavailable []string
	fail := func(name string) { unavailable = append(unavailable, name) }
	if config.Cluster != nil {
		if cluster, err := config.Cluster.Cluster(ctx, false); err == nil {
			inputs.Cluster = &cluster
		} else {
			fail("cluster")
		}
	}
	if inputs.Cluster == nil && config.Local != nil {
		if snapshot, err := config.Local.Snapshot(ctx, false); err == nil {
			inputs.Cluster = &observability.ClusterSnapshot{Cell: snapshot.Cell, ObservedAt: snapshot.ObservedAt,
				Members: []observability.MemberSnapshot{snapshot}}
		} else {
			fail("snapshot")
		}
	}
	if config.Decisions != nil {
		// Only the repeated-hold rule reads decisions: ask for exactly the
		// holds in its window, and treat an incomplete answer as no input
		// rather than as fewer holds.
		result, err := config.Decisions.Query(ctx, decisionlog.Query{Regions: []string{config.Region},
			Kinds: []decisionlog.Kind{decisionlog.KindHeld}, Since: now.Add(-decisionWindow), Limit: maxDecisions})
		switch {
		case err != nil || result.Truncated || result.Partial:
			fail("decisions")
		default:
			inputs.Decisions = result.Decisions
		}
	}
	check := func(name string, err error) {
		if err != nil {
			fail(name)
		}
	}
	var err error
	if config.Rollouts != nil {
		inputs.Rollouts, err = config.Rollouts.Rollouts(ctx)
		check("rollouts", err)
	}
	if config.Volumes != nil {
		inputs.Volumes, err = config.Volumes.Volumes(ctx)
		check("volumes", err)
	}
	if config.Certificates != nil {
		inputs.Certificates, err = config.Certificates.Certificates(ctx)
		check("certificates", err)
	}
	if config.NetBird != nil {
		inputs.Peers, err = config.NetBird.Peers(ctx)
		check("netbird", err)
	}
	if config.Autoscalers != nil {
		inputs.Autoscalers, err = config.Autoscalers.Autoscalers(ctx)
		check("autoscalers", err)
	}
	if config.Budgets != nil {
		inputs.Budgets, err = config.Budgets.Budgets(ctx)
		check("budgets", err)
	}
	if config.Reachability != nil {
		inputs.Reachability = config.Reachability.Reachability(ctx)
	}
	if config.Holds != nil {
		inputs.Holds = config.Holds.Holds(now)
	}
	if config.OCIResources != nil {
		inputs.OCIResources, err = config.OCIResources.OCIResources(ctx)
		check("oci_resources", err)
	}
	if inputs.Cluster != nil {
		// A member that did not answer was not observed: its insights stay
		// open rather than resolve.
		for _, member := range inputs.Cluster.Missing {
			fail("member " + member)
		}
		sections := map[string]bool{}
		var memberSections []string
		for _, member := range inputs.Cluster.Members {
			for section := range member.Errors {
				sections[section] = true
				// Per-member rules name the member's own section, so one
				// member's failure does not hold every member's insights.
				memberSections = append(memberSections, "member "+member.Member+" section "+section)
			}
		}
		for _, section := range slices.Sorted(maps.Keys(sections)) {
			fail("section " + section)
		}
		slices.Sort(memberSections)
		unavailable = append(unavailable, memberSections...)
	}
	return inputs, unavailable
}

// ruleInputs names the inputs each rule reads beyond history: when one is
// unavailable, the rule's open insights and condition timers are kept
// rather than resolved, since a missing observation is not a recovery.
var ruleInputs = map[string][]string{
	"quorum_at_risk":       {"cluster", "snapshot"},
	"no_leader":            {"cluster", "snapshot", "section authority"},
	"member_not_ready":     {"cluster", "snapshot"},
	"jetstream_replicas":   {"cluster", "snapshot", "section nats"},
	"consumer_backlog":     {"cluster", "snapshot", "section nats"},
	"mixed_versions":       {"cluster", "snapshot"},
	"rollout_stalled":      {"cluster", "snapshot", "section placement"},
	"rollout_deadline":     {"rollouts"},
	"member_held":          {"cluster", "snapshot", "section placement", "decisions"},
	"volume_stuck":         {"cluster", "snapshot", "section placement", "volumes"},
	"disk_time_to_full":    {"cluster", "snapshot", "section system"},
	"memory_pressure":      {"cluster", "snapshot", "section system"},
	"clock_skew":           {"cluster", "snapshot", "section system"},
	"oci_errors":           {"cluster", "snapshot", "section oci"},
	"certificate_expiring": {"certificates", "cluster", "snapshot", "section credentials"},
	"netbird_peer":         {"netbird"},
	"autoscaler_at_max":    {"autoscalers"},
	"budget_ceiling":       {"budgets"},
	"oci_drift":            {"oci_resources"},
}

// blindRules lists the rules that lacked an input on this pass.
func blindRules(unavailable []string) map[string]bool {
	blind := map[string]bool{}
	for rule, inputs := range ruleInputs {
		for _, input := range inputs {
			if slices.Contains(unavailable, input) {
				blind[rule] = true
			}
		}
	}
	return blind
}

// insightBlind reports whether an open insight's inputs were unavailable this
// pass, so its absence is not evidence of recovery.
func insightBlind(insight Insight, blind map[string]bool, unavailable []string) bool {
	if insight.inputs == nil {
		return blind[insight.Rule]
	}
	for _, input := range insight.inputs {
		if slices.Contains(unavailable, input) {
			return true
		}
	}
	return false
}

// Evaluate runs every rule once, updates open insights and notifies
// subscribers of changes. It returns the new evaluation.
func (engine *Engine) Evaluate(ctx context.Context) Evaluation {
	now := engine.config.Now().UTC()
	inputs, unavailable := engine.gather(ctx, now)
	engine.mu.Lock()
	defer engine.mu.Unlock()
	inputs.conditions = engine.conditions
	inputs.touched = map[string]struct{}{}
	inputs.owners = engine.owners
	found := map[string]Insight{}
	for _, rule := range engine.rules {
		inputs.rule = rule.Name
		for _, insight := range rule.Evaluate(inputs) {
			if insight.Rule == "" {
				insight.Rule = rule.Name
			}
			if insight.Key == "" {
				insight.Key = insight.Rule + ":" + insight.Entity.Kind + ":" + insight.Entity.ID
			}
			if insight.Region == "" {
				insight.Region = engine.config.Region
			}
			insight.Key = entityid.Derive("insight", insight.Region, insight.Key)
			if insight.Entity.Region == "" {
				insight.Entity.Region = insight.Region
			}
			if existing, duplicate := found[insight.Key]; duplicate && existing.Severity.Rank() >= insight.Severity.Rank() {
				continue
			}
			found[insight.Key] = insight
		}
	}
	blind := blindRules(unavailable)
	// An untouched condition timer resets unless the rule that owns it could
	// not read its inputs: a blind rule keeps its duration-gated timers,
	// while a rule that looked and saw health starts afresh next time.
	for key := range engine.conditions {
		if _, touched := inputs.touched[key]; !touched && !blind[engine.owners[key]] {
			delete(engine.conditions, key)
			delete(engine.owners, key)
		}
	}
	var changes []Change
	for _, key := range slices.Sorted(maps.Keys(found)) {
		insight := found[key]
		insight.LastSeen = now
		previous, wasOpen := engine.open[key]
		switch {
		case !wasOpen:
			insight.FirstSeen = now
			changes = append(changes, Change{Type: ChangeOpened, Time: now, Insight: insight})
		default:
			insight.FirstSeen = previous.FirstSeen
			if insight.Severity.Rank() > previous.Severity.Rank() {
				changes = append(changes, Change{Type: ChangeEscalated, Time: now, Insight: insight})
			}
		}
		engine.open[key] = insight
	}
	for _, key := range slices.Sorted(maps.Keys(engine.open)) {
		if _, still := found[key]; !still {
			if insightBlind(engine.open[key], blind, unavailable) {
				// Not observed this pass: keep it open until a successful
				// observation clears it.
				continue
			}
			resolved := engine.open[key]
			resolved.LastSeen = now
			changes = append(changes, Change{Type: ChangeResolved, Time: now, Insight: resolved})
			delete(engine.open, key)
		}
	}
	insights := slices.Collect(maps.Values(engine.open))
	Rank(insights)
	engine.current = Evaluation{At: now, Insights: insights, Counts: Count(insights), Unavailable: unavailable}
	for _, change := range changes {
		engine.changes = append(engine.changes, change)
		for subscriber := range engine.subscribers {
			select {
			case subscriber.changes <- change:
			default:
			}
		}
	}
	if overflow := len(engine.changes) - changeCapacity; overflow > 0 {
		engine.droppedThrough = engine.changes[overflow-1].Time
		engine.changes = slices.Delete(engine.changes, 0, overflow)
	}
	return engine.current
}

// Current returns the latest evaluation.
func (engine *Engine) Current() Evaluation {
	engine.mu.Lock()
	defer engine.mu.Unlock()
	current := engine.current
	current.Insights = slices.Clone(current.Insights)
	return current
}

// ChangesComplete reports whether every transition at or after since is
// still held: the engine keeps only the newest changeCapacity.
func (engine *Engine) ChangesComplete(since time.Time) bool {
	engine.mu.Lock()
	defer engine.mu.Unlock()
	return engine.droppedThrough.IsZero() || engine.droppedThrough.Before(since)
}

// Changes returns transitions at or after since, oldest first.
func (engine *Engine) Changes(since time.Time) []Change {
	engine.mu.Lock()
	defer engine.mu.Unlock()
	index, _ := slices.BinarySearchFunc(engine.changes, since, func(change Change, at time.Time) int {
		return change.Time.Compare(at)
	})
	return slices.Clone(engine.changes[index:])
}

// Subscribe streams transitions until ctx ends; a subscriber more than
// buffer changes behind loses changes.
func (engine *Engine) Subscribe(ctx context.Context, buffer int) <-chan Change {
	if buffer <= 0 {
		buffer = 32
	}
	subscriber := &changeSubscriber{changes: make(chan Change, buffer)}
	engine.mu.Lock()
	engine.subscribers[subscriber] = struct{}{}
	engine.mu.Unlock()
	context.AfterFunc(ctx, func() {
		engine.mu.Lock()
		delete(engine.subscribers, subscriber)
		engine.mu.Unlock()
		close(subscriber.changes)
	})
	return subscriber.changes
}

func Rank(insights []Insight) {
	slices.SortStableFunc(insights, func(left, right Insight) int {
		if order := cmp.Compare(right.Severity.Rank(), left.Severity.Rank()); order != 0 {
			return order
		}
		if order := cmp.Compare(right.Score, left.Score); order != 0 {
			return order
		}
		if order := left.FirstSeen.Compare(right.FirstSeen); order != 0 {
			return order
		}
		return cmp.Compare(left.Key, right.Key)
	})
}

// ChangeType is what happened to an insight.
type ChangeType string

const (
	ChangeOpened    ChangeType = "opened"
	ChangeEscalated ChangeType = "escalated"
	ChangeResolved  ChangeType = "resolved"
)

// Change is one transition, streamed to the dashboard for toasts and kept
// for summaries.
type Change struct {
	Type    ChangeType `json:"type"`
	Time    time.Time  `json:"time"`
	Insight Insight    `json:"insight"`
}

// Counts tallies insights by severity.
type Counts struct {
	Critical int `json:"critical"`
	Warning  int `json:"warning"`
	Info     int `json:"info"`
}

// Total returns every counted insight.
func (counts Counts) Total() int { return counts.Critical + counts.Warning + counts.Info }

// Count tallies insights by severity.
func Count(insights []Insight) Counts {
	var counts Counts
	for _, insight := range insights {
		switch insight.Severity {
		case SeverityCritical:
			counts.Critical++
		case SeverityWarning:
			counts.Warning++
		default:
			counts.Info++
		}
	}
	return counts
}

// JournalConfig wires one member's journal.
type JournalConfig struct {
	// Region and Member fill Decision.Region and Actor.Member when a caller
	// leaves them empty.
	Region string
	Member string
	// QueueSize and Capacity default to DefaultQueueSize and
	// DefaultCapacity.
	QueueSize int
	Capacity  int
	// Sink and Archive are optional; without them the journal keeps only
	// its in-memory window. They are usually the same *Stream, and may be
	// attached later with Attach once the regional broker is open.
	Sink    Sink
	Archive Archive
	// Log also writes every recorded decision to the structured log, which
	// feeds the observability event bus.
	Log            bool
	PublishTimeout time.Duration
	Now            func() time.Time
}

// Journal is one member's decision recorder and regional index. Record never
// blocks: the decision is indexed in memory at once and queued for the
// background writer started by Run. Decisions recorded by other members of
// the region arrive through Ingest from the stream tail.
type Journal struct {
	config  JournalConfig
	queue   chan Decision
	storage atomic.Pointer[storageHolder]

	mu    sync.RWMutex
	ring  []Decision
	start int
	size  int
	// ids indexes the ring by decision ID. The value reports whether the
	// decision is known to be durable: published by this journal or read
	// back from the stream.
	ids         map[string]bool
	coveredFrom time.Time
	subscribers map[*subscriber]struct{}

	recorded  atomic.Uint64
	dropped   atomic.Uint64
	published atomic.Uint64
	failed    atomic.Uint64
	// replaying is set while the stream tail replays the stored history
	// into memory, so queries report the index as partial.
	replaying atomic.Bool
}

type storageHolder struct {
	sink    Sink
	archive Archive
}

type subscriber struct{ decisions chan Decision }

// NewJournal returns a journal over the given storage.
func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

// Attach sets the durable sink and archive. Decisions recorded before a sink
// is attached stay queued (up to the queue bound) and are published once it
// is.
func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and
// the log line are kept.
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) enqueue(decision Decision) {
	select {
	case journal.queue <- decision:
		queueDepth.Add(1)
	default:
		journal.dropped.Add(1)
		droppedQueueFull.Inc()
	}
}

func (journal *Journal) ingest(decision Decision, durable bool) (bool, bool) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if known, seen := journal.ids[decision.ID]; seen {
		if durable && !known {
			journal.ids[decision.ID] = true
		}
		return false, known || durable
	}
	ingestedTotal.Inc()
	capacity := len(journal.ring)
	if journal.size == capacity {
		evicted := journal.ring[journal.start]
		delete(journal.ids, evicted.ID)
		if evicted.Time.After(journal.coveredFrom) {
			journal.coveredFrom = evicted.Time
		}
		journal.ring[journal.start] = decision
		journal.start = (journal.start + 1) % capacity
	} else {
		journal.ring[(journal.start+journal.size)%capacity] = decision
		journal.size++
	}
	journal.ids[decision.ID] = durable
	for subscriber := range journal.subscribers {
		select {
		case subscriber.decisions <- decision:
		default:
		}
	}
	return true, durable
}

// MarkCoveredFrom records that decisions older than at may exist in the
// archive but not in memory, for example after a bounded warm start.
func (journal *Journal) MarkCoveredFrom(at time.Time) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if at.After(journal.coveredFrom) {
		journal.coveredFrom = at
	}
}

// snapshot returns the indexed decisions, unordered, and the time from which
// the index is complete.
func (journal *Journal) snapshot() ([]Decision, time.Time) {
	journal.mu.RLock()
	defer journal.mu.RUnlock()
	decisions := make([]Decision, 0, journal.size)
	for offset := range journal.size {
		decisions = append(decisions, journal.ring[(journal.start+offset)%len(journal.ring)])
	}
	return decisions, journal.coveredFrom
}

// Query returns matching decisions newest first. A range older than the
// in-memory window is read from the archive when one is attached, and
// reported Partial otherwise.
func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

func (summarizer Summarizer) Summary(ctx context.Context, window time.Duration) (Summary, error) {
	now := time.Now()
	if summarizer.Now != nil {
		now = summarizer.Now()
	}
	now = now.UTC()
	input := SummaryInput{Now: now, Window: window, Scope: summarizer.Scope, AttentionScope: summarizer.AttentionScope}
	if summarizer.Decisions != nil {
		result, err := summarizer.Decisions.Query(ctx, decisionlog.Query{Regions: summarizer.Regions,
			Since: now.Add(-window), Until: now.Add(time.Nanosecond), Limit: decisionlog.MaxQueryLimit})
		if err != nil {
			return Summary{}, err
		}
		input.Decisions = result.Decisions
		input.DecisionsTruncated = result.Truncated
		input.DecisionsPartial = result.Partial
		for _, status := range result.Regions {
			if status.State != decisionlog.RegionOK {
				input.DecisionsPartial = true
				input.Unanswered = append(input.Unanswered, status.Region)
			}
		}
	}
	if summarizer.Insights != nil {
		input.Changes = summarizer.Insights.Changes(now.Add(-window))
		input.Open = summarizer.Insights.Current().Insights
		if retention, ok := summarizer.Insights.(changeRetention); ok {
			input.ChangesTruncated = !retention.ChangesComplete(now.Add(-window))
		}
	}
	return Summarize(input), nil
}

func Summarize(input SummaryInput) Summary {
	since := input.Now.Add(-input.Window)
	scope := input.Scope
	if scope == "" {
		scope = "the region"
	}
	summary := Summary{Window: input.Window, Scope: scope, Generated: input.Now, Open: Count(input.Open)}
	var decisions []decisionlog.Decision
	for _, decision := range input.Decisions {
		if !decision.Time.Before(since) && !decision.Time.After(input.Now) {
			decisions = append(decisions, decision)
		}
	}
	decisionlog.SortNewestFirst(decisions)
	summary.Decisions = len(decisions)
	window := WindowPhrase(input.Window)
	var sentences []string
	// A truncated decision query makes the count a lower bound, which a
	// structured consumer must be able to tell apart from an exact count.
	summary.Partial = input.DecisionsTruncated || input.DecisionsPartial || input.ChangesTruncated
	switch {
	case len(decisions) == 0 && input.DecisionsPartial:
		sentences = append(sentences, fmt.Sprintf("In the last %s no decisions were found in %s, but part of the "+
			"history could not be searched%s.", window, scope, unansweredText(input.Unanswered)))
	case len(decisions) == 0:
		sentences = append(sentences, fmt.Sprintf("In the last %s the orchestrator made no recorded decisions in %s.",
			window, scope))
	default:
		counts := map[decisionlog.Kind]int{}
		for _, decision := range decisions {
			counts[decision.Kind]++
		}
		kinds := slices.SortedFunc(maps.Keys(counts), func(left, right decisionlog.Kind) int {
			if order := cmp.Compare(counts[right], counts[left]); order != 0 {
				return order
			}
			return cmp.Compare(left, right)
		})
		var phrases []string
		for index, kind := range kinds {
			if index == 4 {
				rest := 0
				for _, other := range kinds[4:] {
					rest += counts[other]
				}
				phrases = append(phrases, fmt.Sprintf("%d other", rest))
				break
			}
			phrases = append(phrases, KindPhrase(kind, counts[kind]))
		}
		noun := "decisions"
		if len(decisions) == 1 {
			noun = "decision"
		}
		made := fmt.Sprintf("%d %s", len(decisions), noun)
		if input.DecisionsTruncated || input.DecisionsPartial {
			made = "at least " + made
		}
		sentences = append(sentences, fmt.Sprintf("In the last %s the orchestrator made %s in %s: %s.",
			window, made, scope, joinList(phrases)))
		if input.DecisionsPartial {
			sentences = append(sentences, "Part of the history could not be searched"+
				unansweredText(input.Unanswered)+", so these counts are lower bounds.")
		}
		sentences = append(sentences, notable(decisions)...)
	}
	for _, change := range input.Changes {
		if change.Time.Before(since) || change.Time.After(input.Now) {
			continue
		}
		switch change.Type {
		case ChangeOpened:
			summary.Opened++
		case ChangeResolved:
			summary.Resolved++
		}
	}
	if summary.Opened > 0 || summary.Resolved > 0 {
		atLeast := ""
		if input.ChangesTruncated {
			atLeast = "At least "
		}
		sentence := fmt.Sprintf("%s opened and %s resolved", countNoun(summary.Opened, "problem", "problems"),
			countNoun(summary.Resolved, "problem", "problems"))
		if atLeast != "" {
			sentence = atLeast + lowerFirst(sentence)
		}
		if input.AttentionScope != "" {
			sentence += " in " + input.AttentionScope
		}
		sentences = append(sentences, sentence+".")
	}
	open := slices.Clone(input.Open)
	Rank(open)
	where := ""
	if input.AttentionScope != "" {
		where = " in " + input.AttentionScope
	}
	switch {
	case len(open) == 0:
		sentences = append(sentences, "Nothing needs attention"+where+" right now.")
	default:
		var parts []string
		if summary.Open.Critical > 0 {
			parts = append(parts, countNoun(summary.Open.Critical, "critical problem", "critical problems"))
		}
		if summary.Open.Warning > 0 {
			parts = append(parts, countNoun(summary.Open.Warning, "warning", "warnings"))
		}
		if summary.Open.Info > 0 {
			parts = append(parts, countNoun(summary.Open.Info, "note", "notes"))
		}
		verb := "needs"
		if len(open) > 1 {
			verb = "need"
		}
		sentences = append(sentences, fmt.Sprintf("Now %s %s attention%s, most urgently: %s.", joinList(parts), verb,
			where, strings.TrimSuffix(open[0].Title, ".")))
	}
	summary.Sentences = sentences
	summary.Text = strings.Join(sentences, " ")
	return summary
}

