	put64(file[96:], uint64(len(data)))
	put64(file[104:], uint64(len(data)))
	put64(file[112:], 4096)
	// Go 1.27 locates ELF build metadata through its named section, without a PT_LOAD fallback.
	put32(file[192:], 1)
	put32(file[196:], 1)
	put64(file[200:], 3)
	put64(file[208:], 0x400000)
