func (g *Guest) AssertAbsent(path, label string) error {
	kind, e := g.Kind(path)
	if e != nil {
		return e
	}
	if kind != "" {
		return fmt.Errorf("base image has a conflicting %s: %s", label, path)
	}
	return nil
}
func parents(p string) []string {
	parent := path.Dir(p)
	parts := strings.Split(strings.TrimPrefix(parent, "/"), "/")
	out := []string{"/"}
	current := ""
	for _, part := range parts {
		if part == "" {
			continue
		}
		current += "/" + part
		out = append(out, current)
	}
	return out
}
func (g *Guest) AssertDirectParents(p string) error {
	for _, parent := range parents(p) {
		kind, e := g.Kind(parent)
		if e != nil {
			return e
		}
		if kind != "dir" {
			return fmt.Errorf("guest artifact parent is not a direct directory: %s", parent)
		}
	}
	return nil
}
func (g *Guest) Directory(p string, uid, gid, mode int) error {
	for _, parent := range parents(p) {
		kind, e := g.Kind(parent)
		if e != nil {
			return e
		}
		if kind != "" && kind != "dir" {
			return fmt.Errorf("guest directory parent is not a direct directory: %s", parent)
		}
	}
	kind, e := g.Kind(p)
	if e != nil {
		return e
	}
	if kind != "" && kind != "dir" {
		return fmt.Errorf("guest directory is not a direct directory: %s", p)
	}
	if kind == "" {
		if _, e = g.Call("mkdir-p", p); e != nil {
			return e
		}
	}
	if e = g.AssertDirectParents(p); e != nil {
		return e
	}
	if _, e = g.Call("chown", strconv.Itoa(uid), strconv.Itoa(gid), p); e != nil {
		return e
	}
	_, e = g.Call("chmod", fmt.Sprintf("0%o", mode), p)
	return e
}
func (g *Guest) AssertFile(p string, uid, gid, mode int) error {
	kind, e := g.Kind(p)
	if e != nil {
		return e
	}
	if kind != "file" {
		return fmt.Errorf("installed image path is not a regular file: %s", p)
	}
	meta, e := g.Metadata(p)
	if e != nil {
		return e
	}
	if meta["st_uid"] != uid || meta["st_gid"] != gid || meta["st_mode"]&07777 != mode || meta["st_nlink"] != 1 {
		return fmt.Errorf("installed image file has unexpected metadata: %s", p)
	}
	return nil
}
func (g *Guest) AssertBytes(p, source string) error {
	work, e := os.MkdirTemp("", "ts-image-readback-")
	if e != nil {
		return e
	}
	defer os.RemoveAll(work)
	readback := filepath.Join(work, "readback")
	if _, e = g.Call("download", p, readback); e != nil {
		return e
	}
	a, e := fileDigest(source)
	if e != nil {
		return e
	}
	b, e := fileDigest(readback)
	if e != nil {
		return e
	}
	if a != b {
		return fmt.Errorf("installed image bytes differ from staged input: %s", p)
	}
	return nil
}
func (g *Guest) Upload(source, p string, mode int) error {
	if e := g.AssertDirectParents(p); e != nil {
		return e
	}
	if e := g.AssertAbsent(p, "image artifact"); e != nil {
		return e
	}
	return g.Replace(source, p, mode)
}
func (g *Guest) Replace(source, p string, mode int) error {
	if _, e := g.Call("upload", source, p); e != nil {
		return e
	}
	if _, e := g.Call("chown", "0", "0", p); e != nil {
		return e
	}
	if _, e := g.Call("chmod", fmt.Sprintf("0%o", mode), p); e != nil {
		return e
	}
	if e := g.AssertFile(p, 0, 0, mode); e != nil {
		return e
	}
	return g.AssertBytes(p, source)
}
func fileDigest(p string) (string, error) { return fileHash(p) }
func copyFile(src, dst string, mode os.FileMode) error {
	source, e := os.Open(src)
	if e != nil {
		return e
	}
	defer source.Close()
	output, e := os.OpenFile(dst, os.O_WRONLY|os.O_TRUNC|os.O_CREATE, mode)
	if e != nil {
		return e
	}
	_, e = io.Copy(output, source)
	return errors.Join(e, output.Close(), os.Chmod(dst, mode))
}

func unitFile(name string) string {
	prefix, instance, ok := strings.Cut(name, "@")
	if !ok {
		return name
	}
	return prefix + "@" + path.Ext(instance)
}
func expectedInstallLinks(stage string, names []string) (map[string]string, error) {
	expected := map[string]string{}
	for _, name := range names {
		file := unitFile(name)
		unit := filepath.Join(stage, "etc/systemd/system", file)
		source := "/etc/systemd/system/" + file
		if _, e := os.Stat(unit); os.IsNotExist(e) {
			unit = filepath.Join(stage, "usr/lib/systemd/system", file)
			source = "/usr/lib/systemd/system/" + file
		}
		s, e := os.Lstat(unit)
		if e != nil || !s.Mode().IsRegular() {
			return nil, fmt.Errorf("required systemd unit is not a direct regular file: %s", file)
		}
		b, e := os.ReadFile(unit)
		if e != nil {
			return nil, e
		}
		section := ""
		found := false
		for raw := range strings.SplitSeq(string(b), "\n") {
			line := strings.TrimSpace(raw)
			if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
				continue
			}
			if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
				section = line[1 : len(line)-1]
				continue
			}
			if section != "Install" {
				continue
			}
			key, value, ok := strings.Cut(line, "=")
			if !ok || !slices.Contains([]string{"WantedBy", "RequiredBy", "Alias", "Also"}, key) {
				return nil, fmt.Errorf("unsupported systemd [Install] entry in %s: %s", file, line)
			}
			if key == "Also" {
				for _, other := range strings.Fields(value) {
					if !slices.Contains(names, other) {
						return nil, fmt.Errorf("unsupported systemd Also unit in %s", file)
					}
				}
				continue
			}
			for _, item := range strings.Fields(value) {
				if !regexp.MustCompile(`^[A-Za-z0-9_.@:-]+$`).MatchString(item) {
					return nil, fmt.Errorf("invalid systemd [Install] name in %s: %s", file, item)
				}
				link := item
				if key != "Alias" {
					relationship := "wants"
					if key == "RequiredBy" {
						relationship = "requires"
					}
					link = item + "." + relationship + "/" + name
				}
				if existing, ok := expected[link]; ok && existing != source {
					return nil, fmt.Errorf("conflicting systemd enablement link: %s", link)
				}
				expected[link] = source
				found = true
			}
		}
		if !found {
			return nil, fmt.Errorf("required systemd unit has no enablement links: %s", file)
		}
	}
	return expected, nil
}
func resolveLink(link, target string) string {
	if !strings.HasPrefix(target, "/") {
		target = path.Join("/etc/systemd/system", path.Dir(link), target)
	}
	target = path.Clean(target)
	if strings.HasPrefix(target, "/lib/systemd/system/") {
		target = "/usr" + target
	}
	return target
}
func collectLinks(root string) (map[string]string, error) {
	links := map[string]string{}
	e := filepath.WalkDir(root, func(p string, d fs.DirEntry, e error) error {
		if e != nil {
			return e
		}
		if d.Type()&os.ModeSymlink != 0 {
			target, e := os.Readlink(p)
			if e != nil {
				return e
			}
			rel, e := filepath.Rel(root, p)
			if e != nil {
				return e
			}
			links[rel] = target
		}
		return nil
	})
	return links, e
}
func installLinks(g *Guest, work, repo string, out io.Writer) error {
	stage := filepath.Join(work, "systemd-root")
	for _, dir := range []string{"etc/systemd", "usr/lib/systemd"} {
		if e := os.MkdirAll(filepath.Join(stage, dir), 0755); e != nil {
			return e
		}
	}
	if e := os.Symlink("usr/lib", filepath.Join(stage, "lib")); e != nil {
		return e
	}
	if _, e := g.Call("copy-out", "/etc/systemd/system", filepath.Join(stage, "etc/systemd")); e != nil {
		return e
	}
	if _, e := g.Call("copy-out", "/usr/lib/systemd/system", filepath.Join(stage, "usr/lib/systemd")); e != nil {
		return e
	}
	etc := filepath.Join(stage, "etc/systemd/system")
	for _, name := range append(append([]string{"terrascale-orchestrator-managed-host-start.service", "terrascale-orchestrator-managed-runtime.service", "terrascale-orchestrator-controller.service", "terrascale-orchestrator-host.service"}, NetBirdUnits...), HostUnitFiles...) {
		if e := copyFile(filepath.Join(repo, "deploy/systemd", name), filepath.Join(etc, name), 0644); e != nil {
			return e
		}
	}
	for _, name := range SelfUpdateUnitFiles {
		if e := copyFile(filepath.Join(repo, "deploy/systemd/selfupdate", name), filepath.Join(etc, name), 0644); e != nil {
			return e
		}
	}
	names := append(append(append([]string{}, Units...), HostUnits...), SelfUpdateTimers...)
	files := append(append([]string{}, names...), "terrascale-orchestrator-host-volume-init.service")
	for _, timer := range SelfUpdateTimers {
		files = append(files, strings.TrimSuffix(timer, ".timer")+".service")
	}
	for _, name := range files {
		// An instance is overridden or masked through its own name or its
		// template's.
		for _, n := range slices.Compact([]string{name, unitFile(name)}) {
			for _, dir := range []string{"/run/systemd/system", "/usr/local/lib/systemd/system"} {
				if e := g.AssertAbsent(dir+"/"+n, "systemd unit override"); e != nil {
					return e
				}
			}
			if target, e := os.Readlink(filepath.Join(etc, n)); e == nil && target == "/dev/null" {
				return fmt.Errorf("required systemd unit is masked: %s", n)
			}
		}
		// An instance is defined only by the image's template.
		if name != unitFile(name) {
			for _, dir := range []string{"/etc/systemd/system", "/usr/lib/systemd/system"} {
				if e := g.AssertAbsent(dir+"/"+name, "systemd unit instance"); e != nil {
					return e
				}
			}
		}
		if _, e := os.Stat(filepath.Join(etc, unitFile(name))); e != nil {
			if _, e = os.Stat(filepath.Join(stage, "usr/lib/systemd/system", unitFile(name))); e != nil {
				return fmt.Errorf("missing a required systemd unit: %s", unitFile(name))
			}
		}
	}
	expected, e := expectedInstallLinks(stage, names)
	if e != nil {
		return e
	}
	before, e := collectLinks(etc)
	if e != nil {
		return e
	}
	env := append(append([]string{}, g.Env...), "SYSTEMD_OFFLINE=1")
	if _, e = g.exec(g.ctx, "", env, append([]string{"systemctl", "--root=" + stage, "enable"}, names...)...); e != nil {
		return e
	}
	for _, name := range names {
		state, e := g.exec(g.ctx, "", env, "systemctl", "--root="+stage, "is-enabled", name)
		if e != nil {
			return e
		}
		if state != "enabled" {
			return fmt.Errorf("required systemd unit is not enabled: %s (%s)", name, state)
		}
	}
	after, e := collectLinks(etc)
	if e != nil {
		return e
	}
	for link := range after {
		if _, exists := before[link]; !exists {
			if _, exists = expected[link]; !exists {
				return errors.New("host systemctl generated a different set of enablement links than guest unit [Install] metadata")
			}
		}
	}
	for link, unit := range expected {
		target, exists := after[link]
		if !exists || resolveLink(link, target) != unit {
			return fmt.Errorf("systemd enablement link does not point to its required unit: %s", link)
		}
	}
	for link, target := range after {
		if old, exists := before[link]; exists {
			if old != target {
				return fmt.Errorf("systemctl changed a preexisting unit link: %s", link)
			}
			continue
		}
		guestPath := "/etc/systemd/system/" + link
		if e = g.AssertAbsent(guestPath, "systemd enablement link"); e != nil {
			return e
		}
		if e = g.Directory(path.Dir(guestPath), 0, 0, 0755); e != nil {
			return e
		}
		if _, e = g.Call("ln-s", target, guestPath); e != nil {
			return e
		}
	}
	for link, target := range after {
		if _, exists := expected[link]; !exists {
			continue
		}
		guestPath := "/etc/systemd/system/" + link
		kind, e := g.Kind(guestPath)
		if e != nil {
			return e
		}
		observed, e := g.Call("readlink", guestPath)
		if e != nil {
			return e
		}
		if kind != "symlink" || observed != target {
			return fmt.Errorf("systemd enablement link readback differs: %s", guestPath)
		}
	}
	_, e = fmt.Fprintf(out, "offline systemd enablement links verified=%d\n", len(expected))
	return e
}

func binaryArchitecture(name string) (string, error) {
	f, err := elf.Open(name)
	if err != nil {
		return "", err
	}
	defer f.Close()
	if f.Class != elf.ELFCLASS64 || f.Data != elf.ELFDATA2LSB || (f.Type != elf.ET_EXEC && f.Type != elf.ET_DYN) {
		return "", errors.New("host binary must be a little-endian ELF64 executable")
	}
	switch f.Machine {
	case elf.EM_AARCH64:
		return "arm64", nil
	case elf.EM_X86_64:
		return "amd64", nil
	}
	return "", errors.New("host binary must target Linux arm64 or amd64")
}

func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

